class StackUnderflowError(Exception):
    pass


class ForthInterpreter:
    def __init__(self):
        self.stack = []

    def evaluate(self, input_data):
        lines = input_data.split('\n')
        for line in lines:
            line = line.strip()
            if not line:
                continue
            if line.startswith(':'):
                self.define_word(line)
            else:
                self.execute(line)

    def define_word(self, line):
        name, definition = line[1:].split(' ', 1)
        self.words[name.upper()] = self.compile(definition)

    def compile(self, definition):
        tokens = self.tokenize(definition)
        return self.compile_tokens(tokens)

    def tokenize(self, definition):
        tokens = []
        word = ''
        for char in definition:
            if char.isspace():
                if word:
                    tokens.append(word)
                    word = ''
            elif char.isalnum() or char in '+-*/()':
                word += char
            elif char == ';':
                if word:
                    tokens.append(word)
                    word = ''
                tokens.append(char)
        if word:
            tokens.append(word)
        return tokens

    def compile_tokens(self, tokens):
        compiled = []
        for token in tokens:
            if token == '(':
                compiled.append('PUSH')
            elif token == ')':
                compiled.append('POP')
            elif token == '+':
                compiled.append('ADD')
            elif token == '-':
                compiled.append('SUB')
            elif token == '*':
                compiled.append('MUL')
            elif token == '/':
                compiled.append('DIV')
            elif token == 'DUP':
                compiled.append('DUP')
            elif token == 'DROP':
                compiled.append('DROP')
            elif token == 'SWAP':
                compiled.append('SWAP')
            elif token == 'OVER':
                compiled.append('OVER')
            else:
                compiled.append(token)
        return compiled

    def execute(self, line):
        tokens = self.tokenize(line)
        compiled = self.compile_tokens(tokens)
        self.execute_compiled(compiled)

    def execute_compiled(self, compiled):
        stack = self.stack
        for token in compiled:
            if token == 'PUSH':
                stack.append(int(input('Enter a number: ')))
            elif token == 'POP':
                stack.pop()
            elif token == 'ADD':
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            elif token == 'SUB':
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            elif token == 'MUL':
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            elif token == 'DIV':
                b = stack.pop()
                a = stack.pop()
                if b:
                    stack.append(a // b)
                else:
                    raise ZeroDivisionError
            elif token == 'DUP':
                stack.append(stack[-1])
            elif token == 'DROP':
                stack.pop()
            elif token == 'SWAP':
                b = stack.pop()
                a = stack.pop()
                stack.append(b)
                stack.append(a)
            elif token == 'OVER':
                b = stack[-2]
                a = stack[-1]
                stack.append(b)
                stack.append(a)
            else:
                self.words[token](stack)

    def __getitem__(self, name):
        return self.words.get(name.upper())

    def __setitem__(self, name, value):
        self.words[name.upper()] = value


# Example usage
