import math

class Rational:
    def __init__(self, numer, denom):
        self.numer = numer
        self.denom = denom
        self._reduce()

    def _gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def _reduce(self):
        gcd = self._gcd(self.numer, self.denom)
        if gcd != self.denom:
            self.numer //= gcd
            self.denom //= gcd
        if self.denom < 0:
            self.numer = -self.numer
            self.denom = -self.denom

    def __eq__(self, other):
        return self.numer == other.numer and self.denom == other.denom

    def __repr__(self):
        return f'{self.numer}/{self.denom}'

    def __add__(self, other):
        if isinstance(other, Rational):
            new_numer = self.numer * other.denom + other.numer * self.denom
            new_denom = self.denom * other.denom
            return Rational(new_numer, new_denom)
        else:
            raise TypeError("Unsupported operand type for +")

    def __sub__(self, other):
        if isinstance(other, Rational):
            new_numer = self.numer * other.denom - other.numer * self.denom
            new_denom = self.denom * other.denom
            return Rational(new_numer, new_denom)
        else:
            raise TypeError("Unsupported operand type for -")

    def __mul__(self, other):
        if isinstance(other, Rational):
            new_numer = self.numer * other.numer
            new_denom = self.denom * other.denom
            return Rational(new_numer, new_denom)
        else:
            raise TypeError("Unsupported operand type for *")

    def __truediv__(self, other):
        if isinstance(other, Rational):
            new_numer = self.numer * other.denom
            new_denom = self.denom * other.numer
            return Rational(new_numer, new_denom)
        else:
            raise TypeError("Unsupported operand type for /")

    def __abs__(self):
        return Rational(abs(self.numer), self.denom)

    def __pow__(self, power):
        if isinstance(power, int):
            new_numer = pow(self.numer, power)
            new_denom = pow(self.denom, power)
            return Rational(new_numer, new_denom)
        else:
            raise TypeError("Unsupported operand type for **")

    def __rpow__(self, base):
        if isinstance(base, (int, float)):
            new_numer = pow(base, self.numer / self.denom)
            new_denom = pow(base, self.denom / self.denom)
            return new_numer / new_denom
        else:
            raise TypeError("Unsupported operand type for **")

    def __radd__(self, other):
        return self + other

    def __rsub__(self, other):
        return -self + other

    def __rmul__(self, other):
        return self * other

    def __rtruediv__(self, other):
        return self / other
