APPROACH: Implement the affine cipher encryption and decryption functions using modular arithmetic, ensuring that the encryption key's components are coprime for successful decryption.

```python
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def mod_inverse(a, m):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            gcd, x, y = extended_gcd(b % a, a)
            return gcd, y - (b // a) * x, x

    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError("Modular inverse does not exist")
    return x % m


def encode(plain_text, a, b):
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    m = len(alphabet)
    if gcd(a, m) != 1:
        raise ValueError("a and m are not coprime")
    encoded_text = ""
    for char in plain_text:
        if char.isalpha():
            index = (ord(char.lower()) - ord(alphabet[0])) % m
            encoded_text += alphabet[(a * index + b) % m]
        else:
            encoded_text += char
    return encoded_text


def decode(ciphered_text, a, b):
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    m = len(alphabet)
    if gcd(a, m) != 1:
        raise ValueError("a and m are not coprime")
    inverse_a = mod_inverse(a, m)
    decoded_text = ""
    for char in ciphered_text:
        if char.isalpha():
            index = (ord(char.lower()) - ord(alphabet[0])) % m
            decoded_text += alphabet[(inverse_a * (index - b)) % m]
        else:
            decoded_text += char
    return decoded_text


# Example usage:
print(encode("test", 5, 7))  # Output: "ybty"
print(decode("ybty", 5, 7))  # Output: "test"
