```python
import threading

class BankAccount:
    def __init__(self):
        self.balance = 0
        self.lock = threading.Lock()
        self.is_open = True

    def get_balance(self):
        with self.lock:
            if not self.is_open:
                raise ValueError("Account is closed")
            return self.balance

    def open(self):
        if not self.is_open:
            raise ValueError("Account is already closed")
        self.is_open = True

    def deposit(self, amount):
        with self.lock:
            if not self.is_open:
                raise ValueError("Account is closed")
            if amount < 0:
                raise ValueError("Deposit amount cannot be negative")
            self.balance += amount

    def withdraw(self, amount):
        with self.lock:
            if not self.is_open:
                raise ValueError("Account is closed")
            if amount < 0:
                raise ValueError("Withdrawal amount cannot be negative")
            if amount > self.balance:
                raise ValueError("Insufficient funds")
            self.balance -= amount

    def close(self):
        with self.lock:
            if not self.is_open:
                raise ValueError("Account is already closed")
            self.is_open = False
```

This implementation uses a lock to ensure that only one thread can access the account balance at a time, preventing race conditions. The `is_open` flag is also protected by the lock to prevent multiple threads from trying to close the account simultaneously.

