```python
class Cell:
    def __init__(self):
        self.value = None
        self.callbacks = []

    def add_callback(self, callback):
        self.callbacks.append(callback)

    def remove_callback(self, callback):
        self.callbacks.remove(callback)

    def notify_callbacks(self, new_value):
        for callback in self.callbacks:
            callback(new_value)

    def update(self, new_value):
        if new_value != self.value:
            self.value = new_value
            self.notify_callbacks(new_value)


class InputCell(Cell):
    def __init__(self, initial_value):
        super().__init__()
        self.value = initial_value


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self.inputs = inputs
        self.compute_function = compute_function
        self._dirty = False

    def update(self, new_value):
        if self._dirty:
            return
        self._dirty = True
        new_value = self.compute_function(*[input.value for input in self.inputs])
        super().update(new_value)
        self._dirty = False


class DependencyGraph:
    def __init__(self):
        self.cells = {}

    def add_cell(self, cell):
        self.cells[cell] = set()

    def add_dependency(self, cell1, cell2):
        self.cells[cell1].add(cell2)
        self.cells[cell2].add(cell1)

    def propagate_update(self, cell):
        visited = set()
        stack = [cell]
        while stack:
            current_cell = stack.pop()
            if current_cell not in visited:
