```python
from http.server import BaseHTTPRequestHandler, HTTPServer
import json
import threading

class User:
    def __init__(self, name):
        self.name = name
        self.owes = {}
        self.owed_by = {}
        self.balance = 0.0

class RestAPI:
    def __init__(self):
        self.database = {}
        self.lock = threading.Lock()

    def get_users(self, users=None):
        if users is None:
            users = list(self.database.keys())
        users.sort()
        return users

    def get_user(self, name):
        with self.lock:
            return self.database.get(name, None)

    def update_user(self, name, owes=None, owed_by=None, balance=None):
        with self.lock:
            user = self.database.get(name, User(name))
            if owes is not None:
                user.owes = owes
            if owed_by is not None:
                user.owed_by = owed_by
            if balance is not None:
                user.balance = balance
            self.database[name] = user

    def create_user(self, name):
        with self.lock:
            if name not in self.database:
                self.database[name] = User(name)

    def create_iou(self, lender, borrower, amount):
        with self.lock:
            lender_user = self.get_user(lender)
            borrower_user = self.get_user(borrower)
            if lender_user and borrower_user:
                lender_user.owes[borrower] = lender_user.owes.get(borrower, 0.0) + amount
                borrower_user.owed_by[borrower] = borrower_user.owed_by.get(borrower, 0.0) + amount
                self.update_user(lender, lender_user.owes, lender_user.owed_by, lender_user.balance)
                self.update_user(borrower, borrower_user.owes, borrower_user.owed_by, borrower_user.balance)

    def get(self, url, payload=None):
        if url == '/users':
            return json.dumps({'users': self.get_users(payload)})
        elif url == '/users/' + payload:
            return json.dumps(self.get_user(payload))
        else:
            return 'Not Found'

    def post(self, url, payload=None):
        if url == '/add':
            self.create_user(payload['user'])
            return json.dumps(self.get_user(payload['user']))
        elif url == '/iou':
            self.create_iou(payload['lender'], payload['borrower'], payload['amount'])
            return json.dumps({'users': self.get_users()})
        else:
            return 'Not Found'

class RequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.send_header('Content-type', 'application/json')
        self.end_headers()
        self.wfile.write(bytes(self.server.api.get(self.path, self.path.split('/')[-1]), 'utf-8'))

    def do_POST(self):
        content_length = int(self.headers['Content-Length'])
        payload = json.loads(self.rfile.read(content_length))
        self.send_response(200)
        self.send_header('Content-type', 'application/json')
        self.end_headers()
        self.wfile.write(bytes(self.server.api.post(self.path, json.dumps(payload)), 'utf-8'))

def run_server():
    server_address = ('', 8000)
    httpd = HTTPServer(server_address, RequestHandler)
    httpd.api = RestAPI()
    print('Starting RESTful API on port 8000...')
    httpd.serve_forever()

if __name__ == '__main__':
    threading.Thread(target=run_server).start()
```

This code implements a simple RESTful API using Python's built-in `http.server` module and a dictionary-based database to store user information and IOUs. The API has two endpoints: `/users` and `/users/<name>`, which return a list of all users and a specific user's information, respectively. The `/add` endpoint creates a new user, and the `/iou` endpoint creates a new IOU between two users. The API uses a lock to ensure thread safety when accessing the database.

