    Tree(1, [Tree(4), Tree(5)]),
    Tree(2, [Tree(6, [Tree(7), Tree(8)]), Tree(3, [Tree(9))])])

print(tree.from_pov(6).__dict__())  # Output: {6: [{7: []}, {8: []}]}
print(tree.path_to(6, 9))  # Output: [6, 2, 3, 9]
